const uint row = threadgroup_position_in_grid.x;
const uint tid = thread_position_in_threadgroup.x;
const uint lane = thread_index_in_simdgroup;
const uint sg = simdgroup_index_in_threadgroup;
const uint base = row * H;
threadgroup float part[8];

const bool vec = (H % 4 == 0);
const uint V = H / 4;
half4 xv[4];
half4 wv[4];
float ss = 0.0f;

if (vec) {
    #pragma unroll
    for (uint j = 0; j < 4; j++) {
        uint i = tid + j * 256;
        if (i < V) {
            xv[j] = ld4(x, base + i * 4);
            wv[j] = ld4(w, i * 4);
        }
    }
    #pragma unroll
    for (uint j = 0; j < 4; j++) {
        uint i = tid + j * 256;
        if (i < V) {
            half4 v = xv[j] + ld4(r, base + i * 4);
            xv[j] = v;
            st4(h, base + i * 4, v);
            float4 f = float4(v);
            ss += dot(f, f);
        }
    }
    for (uint i = tid + 1024; i < V; i += 256) {
        half4 v = ld4(x, base + i * 4) + ld4(r, base + i * 4);
        st4(h, base + i * 4, v);
        float4 f = float4(v);
        ss += dot(f, f);
    }
} else {
    for (uint i = tid; i < H; i += 256) {
        half v = half(float(x[base + i]) + float(r[base + i]));
        h[base + i] = v;
        float f = float(v);
        ss += f * f;
    }
}

ss = simd_sum(ss);
if (lane == 0) part[sg] = ss;
threadgroup_barrier(mem_flags::mem_threadgroup);
const float tot = ((part[0] + part[1]) + (part[2] + part[3])) + ((part[4] + part[5]) + (part[6] + part[7]));
const float inv = rsqrt(tot / float(H) + 1e-5f);

if (vec) {
    #pragma unroll
    for (uint j = 0; j < 4; j++) {
        uint i = tid + j * 256;
        if (i < V) st4(y, base + i * 4, half4(float4(xv[j]) * (float4(wv[j]) * inv)));
    }
    for (uint i = tid + 1024; i < V; i += 256) {
        float4 f = float4(ld4(h, base + i * 4));
        float4 wl = float4(ld4(w, i * 4));
        st4(y, base + i * 4, half4(f * (wl * inv)));
    }
} else {
    for (uint i = tid; i < H; i += 256) {
        y[base + i] = half(float(h[base + i]) * inv * float(w[i]));
    }
}

